    "source": "\"\"\"Strictly increasing LIS in O(n log n) with recovery. Returns [length, *one longest strictly increasing subsequence].\"\"\"\n\n\ndef lis(a: list[int]) -> list[int]:\n    tails: list[int] = []  # tails[k] = index of the smallest possible tail of a strictly increasing subsequence of length k+1\n    prev = [-1] * len(a)\n    for i in range(len(a)):\n        lo, hi = 0, len(tails)\n        while lo < hi:\n            mid = (lo + hi) // 2\n            if a[tails[mid]] < a[i]:\n                lo = mid + 1\n            else:\n                hi = mid\n        if lo > 0:\n            prev[i] = tails[lo - 1]\n        if lo == len(tails):\n            tails.append(i)\n        else:\n            tails[lo] = i\n    seq: list[int] = []\n    k = tails[-1] if tails else -1\n    while k >= 0:\n        seq.append(a[k])\n        k = prev[k]\n    seq.reverse()\n    return [len(seq)] + seq\n",
