    "source": "// Strictly increasing LIS in O(n log n) with recovery. Returns [length, one longest strictly increasing subsequence...].\npub fn lis(a: &[i64]) -> Vec<i64> {\n    let mut tails: Vec<usize> = Vec::new(); // tails[k] = index of the smallest possible tail of length k+1\n    let mut prev: Vec<i64> = vec![-1; a.len()];\n    for i in 0..a.len() {\n        let (mut lo, mut hi) = (0usize, tails.len());\n        while lo < hi {\n            let mid = (lo + hi) / 2;\n            if a[tails[mid]] < a[i] { lo = mid + 1; }\n            else { hi = mid; }\n        }\n        if lo > 0 { prev[i] = tails[lo - 1] as i64; }\n        if lo == tails.len() { tails.push(i); }\n        else { tails[lo] = i; }\n    }\n    let mut seq: Vec<i64> = Vec::new();\n    let mut k: i64 = tails.last().map_or(-1, |&t| t as i64);\n    while k >= 0 { seq.push(a[k as usize]); k = prev[k as usize]; }\n    seq.reverse();\n    let mut res = vec![seq.len() as i64];\n    res.extend(seq);\n    res\n}\n",
